chapters.push({"id":15,"name":"Video clips","names":{"hi":"वीडियो क्लिप","pa":"ਵੀਡੀਓ ਕਲਿੱਪ","ur":"ویڈیو کلپس","bn":"ভিডিও ক্লিপ","te":"వీడియో క్లిప్‌లు","mr":"व्हिडिओ क्लिप","ml":"വീഡിയോ ക്ലിപ്പുകൾ","ta":"வீடியோ கிளிப்கள்","gu":"વિડિઓ ક્લિપ","ne":"भिडियो क्लिप"}});
